# region: sift
def sift(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: render
def render(xs, factor=2):
    return [v * factor for v in xs]

# region: intake
def intake(xs, factor=2):
    return [v * factor for v in xs]

# region: digest
def digest(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': min(xs) if xs else 0}

# region: emit
def emit(summary, bar=3):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return emit(digest(intake(render(sift(raw)))))

